#define PAGE_SIZE 4096
typedef unsigned long ADDR;

// Conceptual Page Table Entry (PTE)
struct PTE {
    ADDR frame_num : 20; // Frame Address
    unsigned int present : 1;    // Resides in RAM
    unsigned int writable : 1;
    unsigned int referenced : 1;
    // ... protection bits
};

// Virtual Address (VA) -> Physical Address (PA)
ADDR translate(ADDR va, struct PTE* page_table) {
    ADDR page_num = va / PAGE_SIZE;
    ADDR offset = va % PAGE_SIZE;

    struct PTE entry = page_table[page_num];

    if (!entry.present) {
        // Handle Page Fault (Swap required)
        return 0; // Invalid address indicator
    }

    return (entry.frame_num * PAGE_SIZE) + offset;
}
